import java.util.*;public class DrivingSchedule extends Schedule implements DrivingAPI{private final Set<String>cars=new HashSet<>();public void registerCar(String id){cars.add(id);}public boolean carAvailable(String id){return cars.contains(id);}public void addLesson(Schedule.Lesson lesson){if(lesson.kind()==Kind.PRACTICE&&!carAvailable(lesson.car()))throw new IllegalArgumentException("training car required");super.addLesson(lesson);}public List<Schedule.Lesson>theory(String group){return forGroup(group).stream().filter(l->l.kind()==Kind.THEORY).toList();}public List<Schedule.Lesson>practice(String group){return forGroup(group).stream().filter(l->l.kind()==Kind.PRACTICE).toList();}}
